func TestAttachmentContentReuse(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	registerDevice(t, h, "dev-2")
	content := []byte("shared content")

	mustCreateAttachment(t, h, "dev-1", "att-1", content, 8)
