		for _, url := range []string{
			"/v1/devices/dev-1/attachments",
			"/v1/devices/dev-1/attachments?limit=1&offset=0",
			"/v1/devices/dev-1/attachments?limit=1&offset=1",
			"/v1/devices/dev-2/attachments",
