import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"path/filepath"
	"testing"
)

func digestOf(data []byte) string {
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])
}

func mustRegisterDevice(t *testing.T, s *Store, id string) {
	t.Helper()
	if _, err := s.RegisterDevice(id); err != nil {
